/* Uniform point labels per chart; font controls leave consultation UI untouched. */
(()=>{'use strict';let scheduled=false;
function set(node,size,weight){const value=size+'px';if(node.style.fontSize!==value)node.style.setProperty('font-size',value,'important');if(node.style.fontWeight!==weight)node.style.setProperty('font-weight',weight,'important');}
function refresh(){scheduled=false;const preferences=window.KPPreferences;if(!preferences?.isConfigured())return;const s=preferences.get(),weight=s.fontBold?'700':'400';
 for(const chart of document.querySelectorAll('.v38-chart')){if(chart.closest('#printReport,[contenteditable]'))continue;const width=chart.getBoundingClientRect().width||600;for(const [selector,base] of [['.v38-name',9],['.v38-degree',7.5]]){const ratio=selector==='.v38-name'?({small:.85,medium:1,large:1.2}[s.planetSize]||1):({small:.85,medium:1,large:1.15}[s.degreeSize]||1),size=width/480*base*(s.fontSize/12)*ratio;chart.querySelectorAll(selector).forEach(n=>{if(!n.closest('[contenteditable],[data-manual-text]'))set(n,size,weight);});}}
 for(const chart of document.querySelectorAll('.north9-chart svg')){if(chart.closest('#printReport'))continue;const labels=[...chart.querySelectorAll('text[data-longitude]')];if(!labels.length)continue;const capacity=Math.min(...labels.map(n=>Number(n.dataset.kpOriginalSize||n.getAttribute('font-size'))).filter(n=>n>0));const size=capacity/1.8*(s.fontSize/12)*({small:.85,medium:1,large:1.2}[s.planetSize]||1);labels.forEach(n=>{set(n,size,weight);n.querySelectorAll('[data-kp-degree-label]').forEach(d=>set(d,size,weight));});}
 const style=document.getElementById('kp-uniform-vedic-font')||document.head.appendChild(Object.assign(document.createElement('style'),{id:'kp-uniform-vedic-font'}));const css=`@media screen{#vedic-kundali :is(.v-chart-cell strong,.v-north-house strong){font-size:${s.fontSize}px!important;font-weight:${weight}!important}}`;if(style.textContent!==css)style.textContent=css;
}
function queue(){if(!scheduled){scheduled=true;requestAnimationFrame(refresh);}}
function init(){window.addEventListener('kp-preferences-changed',queue);window.addEventListener('chart-saved',queue);window.addEventListener('resize',queue);const target=document.getElementById('kp-preference-values');if(target)new MutationObserver(queue).observe(target,{childList:true,subtree:true,characterData:true});for(const id of ['home-kundali','kundali','kundali-north','vedic-kundali']){const n=document.getElementById(id);if(n)new MutationObserver(queue).observe(n,{childList:true,subtree:true});}queue();}
window.KPChartTypography=Object.freeze({refresh});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
